ruleToc.chapterList:
#BookText@ul@li@a
<js>
var r=result;
var v=book.getVariable("custom")
var b=[];
if(v!=""){
        for(i=0;i<r.length-v;i++){
                b.push(r[i]);
                }
                result=b;
        }
        result
</js>

